#!/usr/bin/env node
/** Write a crawlable release snapshot into the download pages.
 *
 * The download matrices are rendered by app.js from site/data/release.json, so
 * a crawler (or a visitor with JavaScript disabled) previously saw no version
 * and no file name anywhere on a download surface. This fills the
 * `<!-- download:auto:start -->` region of both download pages with a static
 * sentence plus the asset list, regenerated by the site-refresh workflow from
 * the same release.json the page fetches at runtime.
 *
 * Usage: node scripts/gen-site-download-index.mjs [--check]
 */
import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const RELEASE = path.join(ROOT, 'site', 'data', 'release.json')
const START = '<!-- download:auto:start -->'
const END = '<!-- download:auto:end -->'
const PAGES = [
  { file: path.join(ROOT, 'site', 'download', 'index.html'), lang: 'zh' },
  { file: path.join(ROOT, 'site', 'en', 'download', 'index.html'), lang: 'en' },
]

const escapeHtml = value => String(value).replace(/[&<>"]/g, character => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[character]))

function formatSize(bytes) {
  if (!Number.isFinite(bytes) || bytes <= 0) return ''
  const mb = bytes / (1024 * 1024)
  return mb >= 1 ? `${mb.toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`
}

/** @returns {string} the region body for one language. */
export function renderSnapshot(release, lang) {
  const tag = release?.release?.tag
  if (typeof tag !== 'string' || tag.length === 0) throw new Error('release.json has no tag')
  const published = typeof release.release.published_at === 'string' ? release.release.published_at.slice(0, 10) : ''
  const installers = (release.release.assets ?? []).filter(asset => asset.kind === 'installer')
  const checksums = (release.release.assets ?? []).filter(asset => asset.kind === 'checksum')
  const names = installers.map(asset => asset.name)
  const rows = installers.map(asset => {
    const mirror = asset.gitcode_ok === true ? ' · GitCode' : ''
    const size = formatSize(asset.size)
    return `        <li><code>${escapeHtml(asset.name)}</code>${size ? ` — ${size}` : ''} · GitHub${mirror}</li>`
  }).join('\n')

  if (lang === 'en') {
    return `${START}
      <p class="download-snapshot">Current release <code>${escapeHtml(tag)}</code>${published ? ` (published ${published})` : ''} ships
        ${installers.length} installers and ${checksums.length} checksum files: ${escapeHtml(names.join(', '))}.</p>
      <ul class="download-snapshot__list">
${rows}
      </ul>
      ${END}`
  }
  return `${START}
      <p class="download-snapshot">当前版本 <code>${escapeHtml(tag)}</code>${published ? `（${published} 发布）` : ''} 包含
        ${installers.length} 个安装包与 ${checksums.length} 个校验文件：${escapeHtml(names.join('、'))}。</p>
      <ul class="download-snapshot__list">
${rows}
      </ul>
      ${END}`
}

async function main() {
  const checkOnly = process.argv.includes('--check')
  const release = JSON.parse(await readFile(RELEASE, 'utf8'))
  let drifted = 0
  for (const page of PAGES) {
    const html = await readFile(page.file, 'utf8')
    const start = html.indexOf(START)
    const end = html.indexOf(END)
    if (start === -1 || end === -1 || end < start) throw new Error(`${path.relative(ROOT, page.file)} is missing the download:auto markers`)
    const next = html.slice(0, start) + renderSnapshot(release, page.lang) + html.slice(end + END.length)
    if (next === html) {
      console.log(`download-index: ${path.relative(ROOT, page.file)} already current (${release.release.tag})`)
      continue
    }
    drifted++
    if (checkOnly) {
      console.error(`download-index: ${path.relative(ROOT, page.file)} is stale`)
      continue
    }
    await writeFile(page.file, next)
    console.log(`download-index: updated ${path.relative(ROOT, page.file)} (${release.release.tag})`)
  }
  if (checkOnly && drifted > 0) process.exitCode = 1
}

if (process.argv[1] !== undefined && import.meta.url === `file://${path.resolve(process.argv[1])}`) {
  await main()
}
